import sys, json


def solve(req):
    ebits = req['ebits']
    fbits = req['fbits']
    mode = str(req['mode']).upper()
    pairs = req['pairs']

    width = 1 + ebits + fbits
    mask = (1 << width) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    signbit = 1 << (ebits + fbits)

    def decode(h):
        v = int(h, 16) & mask
        s = v >> (ebits + fbits)
        e = (v >> fbits) & Eall
        f = v & (F - 1)
        return s, e, f

    def cls(s, e, f):
        # kind of operand
        if e == Eall:
            if f == 0:
                return 'inf'
            return 'snan' if (f >> (fbits - 1)) == 0 else 'qnan'
        if e == 0:
            return 'zero' if f == 0 else 'sub'
        return 'norm'

    # ---- inspect every operand / pair for exceptions ----
    invalid = False
    any_nan = False
    inf_signs = set()
    for a, b in pairs:
        s1, e1, f1 = decode(a)
        s2, e2, f2 = decode(b)
        c1 = cls(s1, e1, f1)
        c2 = cls(s2, e2, f2)
        if c1 in ('qnan', 'snan') or c2 in ('qnan', 'snan'):
            any_nan = True
            if c1 == 'snan' or c2 == 'snan':
                invalid = True
            continue  # NaN pair contributes no infinite product
        if (c1 == 'zero' and c2 == 'inf') or (c1 == 'inf' and c2 == 'zero'):
            invalid = True
            continue
        if c1 == 'inf' or c2 == 'inf':
            inf_signs.add(s1 ^ s2)
    if len(inf_signs) > 1:
        invalid = True

    if any_nan or invalid:
        bits = (Eall << fbits) | (1 << (fbits - 1))  # canonical NaN
        return {'bits': format(bits, 'x'), 'flags': ['invalid'] if invalid else []}

    if inf_signs:
        s = next(iter(inf_signs))
        bits = (s << (ebits + fbits)) | (Eall << fbits)
        return {'bits': format(bits, 'x'), 'flags': []}

    # ---- all operands finite: exact sum of products ----
    prods = []  # (m, e, zero_sign) value = m * 2^e
    for a, b in pairs:
        s1, e1, f1 = decode(a)
        s2, e2, f2 = decode(b)
        if e1 == 0:
            m1, ex1 = f1, 1 - bias - fbits
        else:
            m1, ex1 = F + f1, e1 - bias - fbits
        if e2 == 0:
            m2, ex2 = f2, 1 - bias - fbits
        else:
            m2, ex2 = F + f2, e2 - bias - fbits
        m = m1 * m2
        if s1:
            m = -m
        if s2:
            m = -m
        prods.append((m, ex1 + ex2, s1 ^ s2))

    if prods:
        E = min(p[1] for p in prods)
        M = 0
        for m, ex, _ in prods:
            M += m << (ex - E)
    else:
        M, E = 0, 0

    if M == 0:
        # exact zero
        all_neg_zero = len(prods) > 0 and all(m == 0 and zs == 1 for m, _, zs in prods)
        s = 1 if (all_neg_zero or mode == 'RDN') else 0
        return {'bits': format(s << (ebits + fbits), 'x'), 'flags': []}

    sign = 1 if M < 0 else 0
    x_m = -M if M < 0 else M  # exact magnitude = x_m * 2^E

    # ---- round ----
    L = (x_m.bit_length() - 1) + E  # floor(log2(x))
    Q = emin - fbits
    if L - fbits > Q:
        Q = L - fbits
    d = E - Q
    if d >= 0:
        n = x_m << d
        inexact = False
    else:
        k = -d
        div, rem = divmod(x_m, 1 << k)
        half = 1 << (k - 1)
        if mode == 'RNE':
            n = div + 1 if (rem > half or (rem == half and (div & 1))) else div
        elif mode == 'RNA':
            n = div + 1 if rem >= half else div
        elif mode == 'RTZ':
            n = div
        elif mode == 'RUP':
            n = div + 1 if (sign == 0 and rem > 0) else div
        else:  # RDN
            n = div + 1 if (sign == 1 and rem > 0) else div
        inexact = rem != 0

    def ge_pow2(n, Q, K):
        # is n * 2**Q >= 2**K ?  (n >= 0)
        if n == 0:
            return False
        if Q >= K:
            return True
        return n >= (1 << (K - Q))

    # ---- overflow ----
    if n > 0 and ge_pow2(n, Q, emax + 1):
        away = (mode in ('RNE', 'RNA')) or (mode == 'RUP' and sign == 0) or (mode == 'RDN' and sign == 1)
        if away:
            bits = (sign << (ebits + fbits)) | (Eall << fbits)
        else:
            bits = (sign << (ebits + fbits)) | ((Eall - 1) << fbits) | (F - 1)
        return {'bits': format(bits, 'x'), 'flags': ['overflow', 'inexact']}

    flags = set()
    if inexact:
        flags.add('inexact')
        if not ge_pow2(n, Q, emin):  # rounded magnitude below 2**emin
            flags.add('underflow')

    # ---- encode ----
    if n == 0:
        bits = sign << (ebits + fbits)
    elif ge_pow2(n, Q, emin):
        # normal: express in units of 2**(emin-fbits)
        nU = n << (Q - (emin - fbits))
        dd = nU.bit_length() - 1 - fbits
        sig = nU >> dd
        e = dd + 1
        bits = (sign << (ebits + fbits)) | (e << fbits) | (sig - F)
    else:
        f = n << (Q - (emin - fbits))
        bits = (sign << (ebits + fbits)) | f

    return {'bits': format(bits, 'x'), 'flags': list(flags)}


def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.append(json.dumps(solve(json.loads(line))))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


if __name__ == '__main__':
    main()
