"""Independent reference: Fraction-based, scanning encoding."""
from fractions import Fraction as Fr
TWO=Fr(2)

def floorlog2(x):  # x>0 Fraction
    num,den=x.numerator,x.denominator
    L=num.bit_length()-den.bit_length()
    while TWO**L>x: L-=1
    while TWO**(L+1)<=x: L+=1
    return L

def solve(req):
    ebits=req['ebits']; fbits=req['fbits']; mode=req['mode']; pairs=req['pairs']
    bias=2**(ebits-1)-1; F=2**fbits; Eall=2**ebits-1
    emin=1-bias; emax=Eall-1-bias
    width=1+ebits+fbits; mask=(1<<width)-1
    def dec(h):
        v=int(h,16)&mask
        s=v>>(ebits+fbits); e=(v>>fbits)&Eall; f=v&(F-1)
        return s,e,f
    def kind(s,e,f):
        if e==Eall: return 'inf' if f==0 else ('snan' if f>>(fbits-1)==0 else 'qnan')
        if e==0: return 'zero' if f==0 else 'sub'
        return 'norm'
    def val(s,e,f):  # finite only
        if e==0: v=Fr(f)*TWO**(1-bias-fbits)
        else: v=Fr(F+f)*TWO**(e-bias-fbits)
        return -v if s else v
    invalid=False; anynan=False; infsigns=set()
    for a,b in pairs:
        A=dec(a); B=dec(b)
        ka=kind(*A); kb=kind(*B)
        if ka in('qnan','snan') or kb in('qnan','snan'):
            anynan=True
            if ka=='snan' or kb=='snan': invalid=True
            continue
        if (ka=='zero' and kb=='inf') or (ka=='inf' and kb=='zero'):
            invalid=True; continue
        if ka=='inf' or kb=='inf': infsigns.add(A[0]^B[0])
    if len(infsigns)>1: invalid=True
    cnan=(Eall<<fbits)|(1<<(fbits-1))
    if anynan or invalid:
        return format(cnan,'x'), (['invalid'] if invalid else [])
    if infsigns:
        s=next(iter(infsigns))
        return format((s<<(ebits+fbits))|(Eall<<fbits),'x'), []
    prods=[]
    for a,b in pairs:
        A=dec(a); B=dec(b)
        prods.append((val(*A)*val(*B), A[0]^B[0]))
    tot=sum((p for p,_ in prods), Fr(0))
    if tot==0:
        allneg=len(prods)>0 and all(p==0 and zs==1 for p,zs in prods)
        s=1 if (allneg or mode=='RDN') else 0
        return format(s<<(ebits+fbits),'x'), []
    sign=1 if tot<0 else 0
    x=abs(tot)
    L=floorlog2(x)
    Q=max(emin-fbits,L-fbits)
    q=TWO**Q
    t=x/q
    fl=int(t); rem=t-fl
    if mode=='RNE':
        n=fl+1 if (rem>Fr(1,2) or (rem==Fr(1,2) and fl%2==1)) else fl
    elif mode=='RNA':
        n=fl+1 if rem>=Fr(1,2) else fl
    elif mode=='RTZ': n=fl
    elif mode=='RUP': n=fl+1 if (sign==0 and rem>0) else fl
    else: n=fl+1 if (sign==1 and rem>0) else fl
    inexact=(t!=n)
    y=Fr(n)*q
    if n>0 and y>=TWO**(emax+1):
        away=(mode in('RNE','RNA'))or(mode=='RUP' and sign==0)or(mode=='RDN' and sign==1)
        if away: bits=(sign<<(ebits+fbits))|(Eall<<fbits)
        else: bits=(sign<<(ebits+fbits))|((Eall-1)<<fbits)|(F-1)
        return format(bits,'x'),['overflow','inexact']
    flags=[]
    if inexact:
        flags.append('inexact')
        if y<TWO**emin: flags.append('underflow')
    if n==0:
        bits=sign<<(ebits+fbits)
    elif y>=TWO**emin:
        e=f=None
        for ee in range(1,Eall):
            sig=y*TWO**(bias+fbits-ee)
            if sig.denominator==1 and F<=sig.numerator<2*F:
                e=ee; f=sig.numerator-F; break
